"""Compact, updateable index for the autonomous research batch; never edits results."""
from pathlib import Path
from .abstaining_task_value_gate import read,save,fingerprint
ROOT=Path('outputs/ease_iteration_review_v1')

def run():
    ROOT.mkdir(exist_ok=True)
    studies=[('E133','ease_structured_response_v1','Local progress predictions improved; complete-task reconstruction101/144 vs97,12 gains/8 losses.'),('E134','ease_one_step_response_control_v1','One-step-only intervention97/144 vs97;10 gains/10 losses.'),('E135','ease_compact_response_value_v1','Compact task-value reconstruction102/144 vs97;9 gains/4 losses.'),('E136','ease_combined_response_value_v1','Combined gate102/144 vs97 with5 gains/0 losses on fitting; old held15/24 vs15 with1 gain/1 loss. Not promoted.'),('E137','ease_family_consensus_gate_v1','Family-deletion consensus removes gains;97/144. New48-placement test reserved before outcomes.'),('E138','ease_expanded_structured_pairs_v1','1440 additional fitting trajectories,2208 clean paired starts total. Tree gate197/288 vs195,9 gains/7 losses; abstain.'),('E139','ease_rich_structured_value_v1','Richer measured kinematic features: best aggregate196/288 vs195,5 gains/4 losses; abstain.'),('E140','ease_paired_effect_classifier_v1','Paired effect classifiers fail reliable ranking; primary abstains at195/288.'),('E141','ease_learned_history_weights_v1','Learned history weights0.904mm position prediction RMSE vs uniform1.468, but tuned constant0.874 is better.'),('E142','ease_anchored_history_weights_v1','Mass-normalized learned weights0.838mm vs constant0.864; one seed worse, individual robustness screen fails.'),('E143','ease_history_weight_ensemble_v1','Fixed all-three ensemble0.817mm vs0.864;10.5% lower position MSE, prediction screen passes.'),('E144','ease_history_estimator_control_v1','Complete tasks: learned67/96, E120 ensemble72, uniform74, tuned constant70. Learned fails task gate.'),('E145','ease_calibration_prior_control_v1','Measured calibration prior improves motion estimates but completes67/96 vs uniform74;1 gain/8 losses.'),('E146','ease_calibration_prior_learning_v1','Denser measured histories with calibration prior:0.237mm vs0.275,26.1% lower position MSE; all seeds improve.'),('E147','ease_learned_calibration_control_v1','Learned prior71/96 vs matched analytical67;8 gains/4 losses. E120 ensemble72 and uniform74 remain stronger overall.'),('E148','ease_dense_joint_supervision_v1','9614 signed-joint measured branches from738 fitting histories. Frozen learned prior0.177mm vs analytical0.192 on additional query directions.'),('E149','ease_exact_map_control_v1','Privileged exact-map reference76/96, six35/48 and seven41/48. No six-joint gain over prior methods; link/table collisions persist.'),('E150','ease_dense_joint_training_v1','Matched dense-target fine-tuning fails5% prediction-improvement screen; no task/fresh evaluation.'),('E151','ease_home_posture_control_v1','Fixed home-posture objective matched across uniform, learned, E120 ensemble and exact-map controllers; see live status.'),('E152','ease_prior_posture_reference_v1','Additional matched analytical-prior posture reference; see live status.')]
    lines=['# Autonomous iteration review','','E120 remains immutable. The reserved fresh48-placement set is still unopened as of this review. E136 used the already-existing held placements once and did not improve them. All subsequent fitting/development results, including failures and rejected candidates, are retained.','', 'The strongest learned-estimation result so far is E146:26.1% lower measured-next-motion position MSE than its matched analytical prior. Its complete controller improves67 to71 successes out of96, but still trails E120 ensemble72 and uniform74. This is progress in estimation and a matched-control gain, not a validated overall task or unseen-embodiment improvement.','', '| Study | Finding | Report | Video gallery |','|---|---|---|---|'];metadata=[]
    for name,folder,finding in studies:
        root=Path('outputs')/folder;report=f'[report](../{folder}/report.md)' if (root/'report.md').exists() else 'pending';manifest=root/'videos/manifest.json';videos=f'[videos](../{folder}/videos/index.html)' if (root/'videos/index.html').exists() else 'source-context videos or pending';lines.append(f'| {name} | {finding} | {report} | {videos} |');metadata.append(dict(experiment=name,folder=str(root),report_exists=(root/'report.md').exists(),videos=len(read(manifest)['videos']) if manifest.exists() else 0))
    lines+=['','Interpretation: these are adaptive fitting-family development splits on known bodies, not independent final-test estimates. Data-collection policies were not nested end-to-end inside every later fold. Prediction queries are future measured joint increments used only in supervised losses; network inputs are past histories. The newer policy is a learned-weighted analytical motion estimator plus a shared controller, not a flow-matching action policy. Exact kinematics are used only in clearly labeled diagnostics/references.','', 'All success/failure videos are executed-state replays unless their reports explicitly label source-context or kinematic illustrations. Counts include repeated trajectories across comparisons; video counts are not independent trials.',''];(ROOT/'report.md').write_text('\n'.join(lines));save(ROOT/'studies.json',metadata)
    status={}
    for method in ('uniform32','e120_ensemble','learned_prior','privileged_exact_map'):
        root=Path('outputs/ease_home_posture_control_v1')/method;p=root/'records.json'
        if not p.exists():p=root/f'records_{method}.json'
        if p.exists():r=read(p);status[method]=dict(episodes=len(r),success=sum(x['success'] for x in r),complete=(root/'posture_verification.json').exists())
    p=Path('outputs/ease_prior_posture_reference_v1/records.json')
    if p.exists():r=read(p);status['matched_prior']=dict(episodes=len(r),success=sum(x['success'] for x in r),complete=(p.parent/'posture_verification.json').exists())
    save(ROOT/'posture_status.json',status);print(status,flush=True)

if __name__=='__main__':run()
